<!doctype html><html lang="id"><head><meta charset="UTF-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:9px;color:#243d36}h1{font-size:20px}table{width:100%;border-collapse:collapse;margin-top:20px}th{background:#243d36;color:white}td,th{padding:8px;border:1px solid #ddd;text-align:left;overflow-wrap:break-word}tr{page-break-inside:avoid}thead{display:table-header-group}.meta{color:#65736e}.footer{margin-top:20px;font-size:8px}</style></head><body><h1><?= e($report['title']) ?></h1><p class="meta">SIM Inventory · <?= e($report['period']) ?><br>Dicetak: <?= date('d/m/Y H:i') ?> WIB</p><table><thead><tr><?php foreach($report['headers'] as $header): ?><th><?= e($header) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($report['rows'] as $row): ?><tr><?php foreach($row as $cell): ?><td><?= e($cell) ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if(!$report['rows']): ?><tr><td colspan="<?= count($report['headers']) ?>">Tidak ada data pada filter ini.</td></tr><?php endif; ?></tbody></table><p class="footer">Total <?= count($report['rows']) ?> data · Sistem Informasi Manajemen Inventori Barang</p></body></html>
